/* YWAM 7 "Ask us anything" chat: answers from the site's own content (assets/chat-kb.js, generated by build.py).
   No AI and no outside service: questions never leave the visitor's browser. Unknown questions get a
   "send this to our team" email link. */
(function () {
  var box = document.querySelector('.chat7');
  if (!box) return;
  var btn = box.querySelector('.chat7-btn'), panel = box.querySelector('.chat7-p'), log = box.querySelector('.c7-log'),
      form = box.querySelector('.c7-form'), input = form.querySelector('input'), root = box.getAttribute('data-root') || '';
  var KB = null, loading = false, started = false;

  var STOP = ('a an the and or but if of to in on at for with by from is are am was be been do does did can could would should will ' +
    'i me my we our you your it its this that there what whats when where who how why which any some about get go have has ' +
    'tell know want like please hi hello hey thanks thank yes no not just really also much many more so ywam sf san francisco').split(' ');
  var SYN = { price: 'cost', fee: 'cost', fees: 'cost', tuition: 'cost', expensive: 'cost', afford: 'cost', money: 'cost', pay: 'cost', paying: 'cost',
    mom: 'parent', dad: 'parent', mother: 'parent', father: 'parent', son: 'parent', daughter: 'parent', child: 'parent', kid: 'parent', parents: 'parent',
    job: 'work', working: 'work', employment: 'work', career: 'work', study: 'studying', school: 'school', college: 'studying', university: 'studying',
    bedroom: 'room', roommate: 'room', roommates: 'room', private: 'room', own: 'room', donate: 'give', donation: 'give', donations: 'give', giving: 'give', tithe: 'give',
    flight: 'travel', flights: 'travel', fly: 'travel', airfare: 'travel', plane: 'travel', ticket: 'travel', transport: 'travel',
    dangerous: 'safe', danger: 'safe', safety: 'safe', scary: 'safe', crime: 'safe', volunteering: 'volunteer', helping: 'volunteer',
    begin: 'start', starts: 'start', starting: 'start', schedule: 'day', daily: 'day', typical: 'day', timetable: 'day', application: 'apply', applying: 'apply',
    housing: 'live', accommodation: 'live', apartment: 'live', sleep: 'live', food: 'eat', meals: 'eat', meal: 'eat', lunch: 'eat', breakfast: 'eat',
    overseas: 'international', abroad: 'international', foreign: 'international', visa: 'international', youth: 'church', group: 'team', groups: 'team', teams: 'team' };
  function stem(w) { if (w.length > 5 && /ing$/.test(w)) w = w.slice(0, -3); else if (w.length > 4 && /ed$/.test(w)) w = w.slice(0, -2); else if (w.length > 3 && /s$/.test(w) && !/ss$/.test(w)) w = w.slice(0, -1); return w; }
  function words(s) {
    return String(s || '').toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9$]+/g, ' ').split(' ').filter(function (w) { return w && STOP.indexOf(w) < 0; })
      .map(function (w) { return SYN[w] || stem(w); });
  }
  function index() {
    KB.items.forEach(function (it, i) { it.i = i; it.qw = words(it.q); it.kw = words(it.k); it.aw = words(it.a); });
  }
  function score(it, qw) {
    var s = 0;
    qw.forEach(function (w) {
      if (it.qw.indexOf(w) >= 0) s += 3;
      if (it.kw.indexOf(w) >= 0) s += 2;
      if (it.aw.indexOf(w) >= 0) s += 0.5;
    });
    return s;
  }
  function rank(q) {
    var qw = words(q), raw = ' ' + String(q).toLowerCase().replace(/[’']/g, '').replace(/[^a-z0-9$ ]+/g, ' ').replace(/\s+/g, ' ') + ' ';
    return KB.items.map(function (it) {
      var s = qw.length ? score(it, qw) : 0;
      (it.p || []).forEach(function (ph) { if (raw.indexOf(' ' + ph + ' ') >= 0) s += 6; });
      return { it: it, s: s };
    }).filter(function (x) { return x.s > 0; })
      .sort(function (a, b) { return b.s - a.s; });
  }

  function safeHref(h) {
    if (/^(https:|mailto:|tel:)/i.test(h)) return h;
    if (/^[a-z0-9\-\/#?=._%]*$/i.test(h)) return root + h;
    return null;
  }
  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
  function scroll() { log.scrollTop = log.scrollHeight; }
  function say(text, who) { var m = el('div', 'c7-msg ' + (who || 'bot')); m.appendChild(el('p', null, text)); log.appendChild(m); scroll(); return m; }
  function links(m, ls) {
    var row = el('div', 'c7-links');
    (ls || []).forEach(function (l) {
      var h = safeHref(l[1]); if (!h) return;
      var a = el('a', null, l[0] + (/^https:/.test(h) ? ' ↗' : ' →')); a.href = h;
      if (/^https:/.test(h)) { a.target = '_blank'; a.rel = 'noopener'; }
      row.appendChild(a);
    });
    if (row.children.length) m.appendChild(row);
  }
  function chips(list, label) {
    var wrap = el('div', 'c7-chips'); if (label) wrap.appendChild(el('small', null, label));
    list.forEach(function (c) { var b = el('button', null, c.text); b.type = 'button'; b.addEventListener('click', c.go); wrap.appendChild(b); });
    log.appendChild(wrap); scroll();
  }
  function questionChips(items, label) {
    chips(items.map(function (it) { return { text: it.q, go: function () { ask(it.q, it); } }; }), label);
  }
  function topics() {
    chips(KB.topics.map(function (tp) {
      return { text: tp[1], go: function () { say(tp[1], 'me'); say('Here are the questions people ask most. Tap one, or type your own.'); questionChips(KB.items.filter(function (x) { return x.t === tp[0]; }).slice(0, 8)); } };
    }), 'Pick a topic');
  }
  function answer(it) {
    var m = say(it.a); links(m, it.l);
    var rel = KB.items.filter(function (x) { return x.t === it.t && x !== it; }).slice(0, 3);
    if (rel.length) questionChips(rel, 'Related');
  }
  function unknown(q) {
    var c = KB.contact;
    var m = say('I don’t have an answer for that one yet. Our team would love to help.');
    links(m, [['Send this question to our team', 'mailto:' + c.email + '?subject=' + encodeURIComponent('Question from the website') + '&body=' + encodeURIComponent(q)], ['Call ' + c.phone, c.tel]]);
    chips([{ text: 'Show me the topics', go: function () { topics(); } }]);
  }
  function ask(q, picked) {
    q = String(q || '').trim(); if (!q) return;
    say(q, 'me');
    if (picked) { answer(picked); return; }
    var r = rank(q);
    if (!r.length || r[0].s < 2.5) { unknown(q); return; }
    answer(r[0].it);
  }
  function start() {
    if (started) return; started = true;
    say('Hi! I can answer questions about the DTS, volunteering, bringing a team, giving, the Ellis Room and more. Ask me anything, or pick a topic.');
    topics();
  }
  function load(then) {
    if (KB) return then();
    if (loading) return; loading = true;
    var s = document.createElement('script'); s.src = box.getAttribute('data-kb'); s.async = true;
    s.onload = function () { KB = window.YWAM_KB; if (!KB) return fail(); index(); then(); };
    s.onerror = fail;
    document.head.appendChild(s);
  }
  function fail() { loading = false; say('Sorry, the answers didn’t load. You can reach us by email or phone below.'); }

  function set(open) {
    btn.setAttribute('aria-expanded', String(open)); panel.hidden = !open; box.classList.toggle('open', open);
    if (open) load(function () { start(); setTimeout(function () { input.focus({ preventScroll: true }); }, 30); });
  }
  btn.addEventListener('click', function () { set(panel.hidden); });
  box.querySelector('.c7-x').addEventListener('click', function () { set(false); btn.focus(); });
  addEventListener('keydown', function (e) { if (e.key === 'Escape' && !panel.hidden) { set(false); btn.focus(); } });
  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var q = input.value; input.value = '';
    load(function () { start(); ask(q); });
  });
})();
